package apache

import (
	"bytes"
	"context"
	"fmt"
	"os"
	"path/filepath"
	"strings"
	"syscall"

	"svngo/internal/fsutil"
	"svngo/internal/ipacl"
)

// The SVN client IP allow list is enforced by Apache, which serves the SVN
// paths itself. httpd.conf includes a generated file of mod_rewrite rules that
// answer 403 in the translate phase, before authentication, for clients
// outside the list. Changing the list rewrites the file, tests the
// configuration and gracefully restarts httpd (SIGUSR1): the parent process
// keeps running and in-flight requests finish.

const accessFile = "svn-access.conf"

// svnPathRule matches every SVN request path: /svn and all locations, i.e.
// anything except the admin UI and the bare "/" redirect.
const svnPathRule = `"^/(?!admin(?:/|$))."`

// AccessFile is the generated rules file included by httpd.conf.
func AccessFile(runDir string) string { return filepath.Join(runDir, accessFile) }

// SvnAccessConf renders the rules restricting SVN paths to allow. An empty
// list means no restriction; otherwise loopback is always allowed.
func SvnAccessConf(allow ipacl.List) string {
	var b strings.Builder
	b.WriteString("# Generated by SvnGo - SVN client IP allow list. Do not edit.\n")
	if allow.Empty() {
		b.WriteString("# no restriction\n")
		return b.String()
	}
	// One condition per network keeps every line short; conditions are ANDed,
	// so the rule fires only when the client matches none of them.
	for _, c := range ipacl.Merge(ipacl.Loopback, allow).CIDRs() {
		fmt.Fprintf(&b, "RewriteCond expr \"! -R '%s'\"\n", c)
	}
	b.WriteString("RewriteRule " + svnPathRule + " - [F,L]\n")
	return b.String()
}

// WriteSvnAccess writes the rules file; use it before httpd starts.
func WriteSvnAccess(runDir string, allow ipacl.List) error {
	return fsutil.AtomicWrite(AccessFile(runDir), []byte(SvnAccessConf(allow)))
}

// ApplySvnAccess replaces the rules file after testing the configuration with
// the new rules and gracefully restarts a running httpd. On failure the
// current file and Apache are left untouched.
func (ap *Supervisor) ApplySvnAccess(ctx context.Context, allow ipacl.List) error {
	return ap.applyInclude(ctx, AccessFile(ap.cfg.RunDir), "SVNGO_SVN_ACCESS_CONF", []byte(SvnAccessConf(allow)))
}

// applyInclude replaces a generated include file (live, passed to httpd as
// envKey) after `httpd -t` accepted the new content, then restarts httpd
// gracefully. Unchanged content is a no-op.
func (ap *Supervisor) applyInclude(ctx context.Context, live, envKey string, data []byte) error {
	ap.applyMu.Lock()
	defer ap.applyMu.Unlock()
	if cur, err := os.ReadFile(live); err == nil && bytes.Equal(cur, data) {
		return nil
	}
	tmp := live + ".new"
	if err := fsutil.AtomicWrite(tmp, data); err != nil {
		return err
	}
	defer os.Remove(tmp)
	if err := ap.test(ctx, envKey+"="+tmp); err != nil {
		return err
	}
	if err := os.Rename(tmp, live); err != nil {
		return err
	}
	ap.mu.Lock()
	defer ap.mu.Unlock()
	if ap.running && ap.cmd != nil && ap.cmd.Process != nil {
		if err := ap.cmd.Process.Signal(syscall.SIGUSR1); err != nil {
			return fmt.Errorf("graceful restart of Apache failed: %w", err)
		}
	}
	return nil
}
